    async def settle_managed_repository_workspace_cleanup_intent(
        self,
        owner_id: str,
        *,
        owner_kind: str,
        scope: str,
        runtime_incarnation: str,
        intent_generation: int,
        claimant: str,
        claim_token: int,
    ) -> bool:
        """Atomically publish cleanup-complete and the exact final projection."""

        if owner_kind not in {"job", "thread"} or scope not in {
            "workspace_container",
            "ide",
        }:
            return False
        if (
            isinstance(intent_generation, bool)
            or not isinstance(intent_generation, int)
            or intent_generation <= 0
        ):
            return False
        if (
            not isinstance(claimant, str)
            or not claimant
            or isinstance(claim_token, bool)
            or not isinstance(claim_token, int)
            or claim_token <= 0
        ):
            return False
        try:
            owner_uuid = UUID(str(owner_id))
            expected_runtime = _canonical_uuid_text(
                runtime_incarnation, label="managed repository cleanup runtime"
            )
        except (TypeError, ValueError, RuntimeError):
            return False
        table = "jobs" if owner_kind == "job" else "threads"
        json_column = "context" if owner_kind == "job" else "metadata"
        timestamp_column = "updated_at" if owner_kind == "job" else "last_activity"
        state_key = "ide_session" if scope == "ide" else "workspace_container"
        async with self.acquire() as conn:
            async with conn.transaction():
                owner = await conn.fetchrow(
                    f"SELECT status::text AS owner_status, {json_column} AS state "
                    f"FROM {table} "
                    "WHERE id = $1 FOR UPDATE",
                    owner_uuid,
                )
                observed_intent = await conn.fetchrow(
                    "SELECT resource_policy FROM "
                    "managed_repository_workspace_cleanup_intents "
                    "WHERE owner_kind = $1 AND owner_id = $2 AND scope = $3 "
                    "AND runtime_incarnation = $4::uuid "
                    "AND intent_generation = $5",
                    owner_kind,
                    owner_uuid,
                    scope,
                    expected_runtime,
                    intent_generation,
                )
                if observed_intent is None:
                    return False
                if (
                    owner is not None
                    and str(observed_intent.get("resource_policy") or "")
                    == "terminal_reclaim"
                ):
                    try:
                        observed_state = _strict_json_object(
                            owner.get("state"), label=json_column
                        )
                    except RuntimeError:
                        return False
                    if (
                        await self._lock_terminal_workspace_reclaim_authority(
                            conn,
                            owner_kind=owner_kind,
                            owner_id=owner_uuid,
                            owner_status=str(owner.get("owner_status") or ""),
                            owner_state=observed_state,
                        )
                        is None
                    ):
                        return False
                intent = await conn.fetchrow(
                    "SELECT * FROM managed_repository_workspace_cleanup_intents "
                    "WHERE owner_kind = $1 AND owner_id = $2 AND scope = $3 "
                    "AND runtime_incarnation = $4::uuid "
                    "AND intent_generation = $5 FOR UPDATE",
                    owner_kind,
                    owner_uuid,
                    scope,
                    expected_runtime,
                    intent_generation,
                )
                if intent is None:
                    return False
                if intent.get("result_kind") == "superseded":
                    return False
                if intent.get("result_kind") == "settled":
                    if owner is None:
                        return True
                    return await conn.fetchval(
                        "SELECT managed_repository_workspace_cleanup_projection_is_settled("
                        "$1, $2, $3, $4, "
                        f"{json_column} #>> $5::text[], "
                        f"{json_column} #>> $6::text[]) FROM {table} WHERE id = $2",
                        owner_kind,
                        owner_uuid,
                        scope,
                        expected_runtime,
                        [state_key, _STATELESS_RUNTIME_INCARNATION_KEY],
                        [state_key, "status"],
                    )
                if (
                    intent.get("claimed_by") != claimant
                    or int(intent.get("claim_token") or 0) != claim_token
                    or intent.get("claim_expires_at") is None
                    or not bool(
                        await conn.fetchval(
                            "SELECT $1::timestamptz > now()",
                            intent["claim_expires_at"],
                        )
                    )
                ):
                    return False
                if intent.get("resources_captured_at") is None:
                    return False
                has_receipt = bool(
                    await conn.fetchval(
                        "SELECT EXISTS (SELECT 1 FROM "
                        "managed_repository_process_zero_receipts "
                        "WHERE owner_kind = $1 AND owner_id = $2 "
                        "AND scope = $3 AND provisioner = 'k8s' "
                        "AND runtime_incarnation = $4)",
                        owner_kind,
                        owner_uuid,
                        scope,
                        expected_runtime,
                    )
                )
                if not has_receipt:
                    return False
                next_state: dict[str, Any] | None = None
                if owner is not None:
                    try:
                        state = _strict_json_object(
                            owner.get("state"), label=json_column
                        )
                    except RuntimeError:
                        return False
                    raw_runtime = state.get(state_key)
                    if not isinstance(raw_runtime, dict):
                        return False
                    raw_uid = raw_runtime.get(_STATELESS_RUNTIME_INCARNATION_KEY)
                    current_runtime = None
                    if raw_uid is not None:
                        try:
                            current_runtime = _canonical_uuid_text(
                                raw_uid,
                                label="managed repository cleanup runtime",
                            )
                        except RuntimeError:
                            return False
                    target = str(intent["target_disposition"])
                    already_target = bool(
                        str(raw_runtime.get("status") or "") == target
                        and (
                            current_runtime == expected_runtime
                            or (
                                owner_kind == "thread"
                                and scope == "workspace_container"
                                and target == "deleted"
                                and current_runtime is None
                            )
                        )
                    )
                    if not already_target and (
                        current_runtime != expected_runtime
                        or str(raw_runtime.get("status") or "")
                        != "retiring_process_zero"
                    ):
                        return False
                    next_runtime = dict(raw_runtime)
                    next_runtime.update(
                        {
                            "status": target,
                            "pod_ip": None,
                        }
                    )
                    if scope == "workspace_container":
                        next_runtime["pod_name"] = None
                        if target == "suspended" and intent.get("suspended_at"):
                            next_runtime["suspended_at"] = intent[
                                "suspended_at"
                            ].isoformat()
                        if target == "suspended":
                            next_runtime["_snapshot_restore_required"] = bool(
                                intent.get("snapshot_restore_required")
                            )
                        # A resumable stateless End must clear the retired UID
                        # before Resume can mint a successor. Permanent
                        # terminal reclaim is different: the owner-delete
                        # trigger still needs that immutable UID to select and
                        # authenticate this exact settled cleanup intent.
                        if owner_kind == "thread" and target == "deleted":
                            next_runtime[_STATELESS_RUNTIME_INCARNATION_KEY] = (
                                expected_runtime
                                if intent.get("resource_policy") == "terminal_reclaim"
                                else None
                            )
                    else:
                        next_runtime["code_server_url"] = None
                        next_runtime["stopped_at"] = datetime.now(
                            timezone.utc
                        ).isoformat()
                    next_state = dict(state)
                    next_state[state_key] = next_runtime

                marked = await conn.execute(
                    "UPDATE managed_repository_workspace_cleanup_intents "
                    "SET cleanup_completed_at = now(), settled_at = now(), "
                    "result_kind = 'settled', phase = 'settled', "
                    "claimed_by = NULL, "
                    "claim_expires_at = NULL WHERE id = $1 "
                    "AND settled_at IS NULL AND claimed_by = $2 "
                    "AND claim_token = $3 AND claim_expires_at > now()",
                    intent["id"],
                    claimant,
                    claim_token,
                )
                if marked != "UPDATE 1":
                    return False
                if owner is not None:
                    updated = await conn.execute(
                        f"UPDATE {table} SET {json_column} = $2::jsonb, "
                        f"{timestamp_column} = CURRENT_TIMESTAMP WHERE id = $1",
                        owner_uuid,
                        json.dumps(next_state),
                    )
                    if updated != "UPDATE 1":
                        raise RuntimeError("workspace cleanup projection was lost")
                return True

    async def restore_settled_thread_workspace_cleanup_projection(
        self, thread_id: str, *, runtime_incarnation: str, intent_generation: int
    ) -> bool:
        """Replay a settled terminal receipt without changing its authority.

        The database locks owner -> queue -> intent and permits only the exact
        terminal projection. This also repairs the old soft-End null-UID shape;
        it never reactivates a runtime or alters a settled cleanup receipt.
        """
        async with self.acquire() as conn:
            return bool(
                await conn.fetchval(
                    "SELECT restore_settled_thread_workspace_cleanup_projection("
                    "$1::uuid, $2::text, $3::bigint)",
                    UUID(str(thread_id)),
                    runtime_incarnation,
                    intent_generation,
                )
            )

    async def supersede_managed_repository_workspace_cleanup_intent(
        self,
        owner_id: str,
        *,
        owner_kind: str,
        scope: str,
        runtime_incarnation: str,
        claimant: str,
        claim_token: int,
    ) -> bool:
        """Settle stale A without granting authority over B's stable names."""

        if owner_kind not in {"job", "thread"} or scope not in {
            "workspace_container",
            "ide",
        }:
            return False
        try:
            owner_uuid = UUID(str(owner_id))
            retired_runtime = _canonical_uuid_text(
                runtime_incarnation, label="stale cleanup runtime"
            )
        except (TypeError, ValueError, RuntimeError):
            return False
        if (
            not isinstance(claimant, str)
            or not claimant
            or isinstance(claim_token, bool)
            or not isinstance(claim_token, int)
            or claim_token <= 0
        ):
            return False
        table = "jobs" if owner_kind == "job" else "threads"
        json_column = "context" if owner_kind == "job" else "metadata"
        async with self.acquire() as conn:
            async with conn.transaction():
                owner = await conn.fetchrow(
                    f"SELECT {json_column} AS state FROM {table} "
                    "WHERE id = $1 FOR UPDATE",
                    owner_uuid,
                )
                if owner is None:
                    return False
                try:
                    state = _strict_json_object(owner.get("state"), label=json_column)
                except RuntimeError:
                    return False
                if (
                    _different_valid_k8s_runtime(
                        state, scope=scope, retired_runtime=retired_runtime
                    )
                    is None
                ):
                    return False
                if not bool(
                    await conn.fetchval(
                        "SELECT EXISTS (SELECT 1 FROM "
                        "managed_repository_process_zero_receipts "
                        "WHERE owner_kind = $1 AND owner_id = $2 "
                        "AND scope = $3 AND provisioner = 'k8s' "
                        "AND runtime_incarnation = $4)",
                        owner_kind,
                        owner_uuid,
                        scope,
                        retired_runtime,
                    )
                ):
                    return False
                intent = await conn.fetchrow(
                    "SELECT id, result_kind, capture_complete, claimed_by, "
                    "claim_token, claim_expires_at FROM "
                    "managed_repository_workspace_cleanup_intents "
                    "WHERE owner_kind = $1 AND owner_id = $2 AND scope = $3 "
                    "AND runtime_incarnation = $4::uuid "
                    "ORDER BY intent_generation DESC LIMIT 1 FOR UPDATE",
                    owner_kind,
                    owner_uuid,
                    scope,
                    retired_runtime,
                )
                if intent is None:
                    return True
                if intent.get("result_kind") == "superseded":
                    return True
                if intent.get("result_kind") is not None:
                    return False
                if (
                    intent.get("capture_complete") is not True
                    or intent.get("claimed_by") != claimant
                    or int(intent.get("claim_token") or 0) != claim_token
                    or intent.get("claim_expires_at") is None
                    or not bool(
                        await conn.fetchval(
                            "SELECT $1::timestamptz > now()",
                            intent["claim_expires_at"],
                        )
                    )
                ):
                    return False
                result = await conn.execute(
                    "UPDATE managed_repository_workspace_cleanup_intents "
                    "SET cleanup_completed_at = now(), settled_at = now(), "
                    "phase = 'superseded', result_kind = 'superseded', "
                    "claimed_by = NULL, claim_expires_at = NULL "
                    "WHERE id = $1 AND settled_at IS NULL "
                    "AND claimed_by = $2 AND claim_token = $3 "
                    "AND claim_expires_at > now()",
                    intent["id"],
                    claimant,
                    claim_token,
                )
                return result == "UPDATE 1"

    async def settle_managed_repository_workspace_after_process_zero(
        self,
        owner_id: str,
        *,
        owner_kind: str,
        runtime_incarnation: str,
    ) -> bool:
        """Compatibility settlement requiring a prepared exact cleanup intent."""

        intent = await self.get_managed_repository_workspace_cleanup_intent(
            owner_id,
            owner_kind=owner_kind,
            scope="workspace_container",
            runtime_incarnation=runtime_incarnation,
        )
        if intent is None:
            return False
        if intent.get("result_kind") == "settled":
            # Replay the exact atomic projection check without reopening or
            # reclaiming a terminal intent.  A historical successor injected
            # after settlement still makes this return False.
            return await self.settle_managed_repository_workspace_cleanup_intent(
                owner_id,
                owner_kind=owner_kind,
                scope="workspace_container",
                runtime_incarnation=runtime_incarnation,
                intent_generation=int(intent["intent_generation"]),
                claimant="compat-settle-replay",
                claim_token=1,
            )
        claimant = f"compat-settle:{uuid4()}"
        claimed = await self.claim_managed_repository_workspace_cleanup_intent(
            str(intent["id"]), claimant=claimant
        )
        if claimed is None:
            return False
        return await self.settle_managed_repository_workspace_cleanup_intent(
            owner_id,
            owner_kind=owner_kind,
            scope="workspace_container",
            runtime_incarnation=runtime_incarnation,
            intent_generation=int(intent["intent_generation"]),
            claimant=claimant,
            claim_token=int(claimed["claim_token"]),
        )

    async def managed_repository_workspace_process_zero_cleanup_state(
        self,
        owner_id: str,
        *,
        owner_kind: str,
        runtime_incarnation: str,
    ) -> str | None:
        """Return pending/settled/superseded cleanup intent authority."""

        intent = await self.get_managed_repository_workspace_cleanup_intent(
            owner_id,
            owner_kind=owner_kind,
            scope="workspace_container",
            runtime_incarnation=runtime_incarnation,
        )
        if intent is None:
            return None
        result_kind = intent.get("result_kind")
        if result_kind in {"settled", "superseded"}:
            return str(result_kind)
        if intent.get("resources_captured_at") is None:
            return "capture_pending"
        if await self.managed_repository_workspace_process_zero_is_current(
            owner_id,
            owner_kind=owner_kind,
            scope="workspace_container",
            provisioner="k8s",
            runtime_incarnation=runtime_incarnation,
        ):
            return "current"
        return "pending"

    async def stateless_thread_workspace_creation_requires_authority(
        self, thread_id: str
    ) -> bool | None:
        """Return whether a direct session create must carry nonce authority."""

        try:
            thread_uuid = UUID(str(thread_id))
        except (TypeError, ValueError):
            return None
        async with self.acquire() as conn:
            lane = await conn.fetchval(
                "SELECT execution_lane FROM threads WHERE id = $1",
                thread_uuid,
            )
        if lane is None:
            return None
        return str(lane) == "stateless"

    async def prepare_stateless_thread_workspace_creation(
        self,
        thread_id: str,
        *,
        proposed_generation: str,
        mode: str,
        expected_runtime_incarnation: str | None = None,
    ) -> dict[str, Any]:
        """Persist/recover one exact Kubernetes create authority.

        A newly persisted marker starts with ``attempted=false``.  A separate
        false-to-true CAS is the only authorization to issue a Kubernetes
        mutation.  Once attempted, an absent Pod can never cause a second
        name-based create; a retry may only adopt a Pod carrying this exact
        generation and owner identity.

        Supplying ``expected_runtime_incarnation`` rotates authority only from
        an already-proven exact-terminal runtime.  The caller performs that
        Kubernetes proof while holding the distributed workspace lifecycle
        lock, then uses this transaction before clearing the old UID.
        """

        try:
            thread_uuid = UUID(str(thread_id))
        except (TypeError, ValueError):
            return {"state": "missing"}
        _canonical_uuid_text(
            proposed_generation,
            label="stateless runtime creation generation",
        )
        if mode not in {"create", "restore"}:
            raise ValueError("stateless runtime creation mode is invalid")
        expected_runtime = None
        if expected_runtime_incarnation is not None:
            expected_runtime = _canonical_uuid_text(
                expected_runtime_incarnation,
                label="stateless workspace runtime incarnation",
            )

        async with self.acquire() as conn:
            async with conn.transaction():
                row = await conn.fetchrow(
                    "SELECT status::text AS status, execution_lane, "
                    "runtime_generation, metadata "
                    "FROM threads WHERE id = $1 FOR UPDATE",
                    thread_uuid,
                )
                if row is None:
                    return {"state": "missing"}
                generation = _canonical_uuid_text(
                    str(row.get("runtime_generation") or ""),
                    label="stateless thread runtime generation",
                )
                try:
                    metadata, workspace, runtime, marker = (
                        _stateless_runtime_creation_context(row)
                    )
                except RuntimeError as exc:
                    return {"state": "blocked", "reason": str(exc)}
                if workspace.get("provisioner") != "k8s":
                    return {"state": "blocked", "reason": "workspace is not k8s"}
                restore_value = workspace.get("_snapshot_restore_required", False)
                if (
                    "_snapshot_restore_required" in workspace
                    and type(restore_value) is not bool
                ):
                    return {
                        "state": "blocked",
                        "reason": "snapshot restore marker is malformed",
                    }
                if (restore_value is True) is not (mode == "restore"):
                    return {
                        "state": "blocked",
                        "reason": "workspace creation mode disagrees with restore intent",
                    }

                if expected_runtime is None:
                    if runtime is not None:
                        return {
                            "state": "runtime",
                            "runtime_incarnation": runtime,
                            "creation": marker,
                        }
                    if marker is not None:
                        return {"state": "pending", "creation": marker}
                    return {
                        "state": "blocked",
                        "reason": "workspace creation authority was not pre-armed",
                    }
                else:
                    if runtime != expected_runtime:
                        return {
                            "state": "blocked",
                            "reason": "workspace runtime changed before recreation",
                        }

                next_marker = {
                    "generation": generation,
                    "mode": mode,
                    "attempted": False,
                    "replaces_uid": expected_runtime,
                }
                workspace[_STATELESS_RUNTIME_CREATION_KEY] = next_marker
                metadata["workspace_container"] = workspace
                result = await conn.execute(
                    """
                    UPDATE threads
                    SET metadata = $2::jsonb,
                        last_activity = CURRENT_TIMESTAMP
                    WHERE id = $1
                    """,
                    thread_uuid,
                    json.dumps(metadata),
                )
                if result != "UPDATE 1":
                    raise RuntimeError(
                        "thread disappeared while arming workspace create"
                    )
                return {"state": "prepared", "creation": next_marker}

    async def claim_stateless_thread_workspace_creation_attempt(
        self,
        thread_id: str,
        *,
        generation: str,
    ) -> bool:
        """CAS one durable create marker from unattempted to attempted."""

        try:
            thread_uuid = UUID(str(thread_id))
        except (TypeError, ValueError):
            return False
        generation = _canonical_uuid_text(
            generation,
            label="stateless runtime creation generation",
        )
        async with self.acquire() as conn:
            async with conn.transaction():
                row = await conn.fetchrow(
                    "SELECT status::text AS status, execution_lane, "
                    "runtime_generation, metadata "
                    "FROM threads WHERE id = $1 FOR UPDATE",
                    thread_uuid,
                )
                if row is None:
                    return False
                try:
                    metadata, workspace, runtime, marker = (
                        _stateless_runtime_creation_context(row)
                    )
                except RuntimeError:
                    return False
                if (
                    runtime is not None
                    or marker is None
                    or marker["generation"] != generation
                    or marker["attempted"] is not False
                ):
                    return False
                marker["attempted"] = True
                workspace[_STATELESS_RUNTIME_CREATION_KEY] = _persisted_creation_marker(
                    marker
                )
                metadata["workspace_container"] = workspace
                result = await conn.execute(
                    "UPDATE threads SET metadata = $2::jsonb, "
                    "last_activity = CURRENT_TIMESTAMP WHERE id = $1",
                    thread_uuid,
                    json.dumps(metadata),
                )
                return result == "UPDATE 1"

    async def validate_stateless_thread_workspace_creation_attempt(
        self,
        thread_id: str,
        *,
        generation: str,
        attempted: bool,
        expected_runtime_incarnation: str | None = None,
    ) -> bool:
        """Read one exact creation state under the thread authority lock."""

        try:
            thread_uuid = UUID(str(thread_id))
        except (TypeError, ValueError):
            return False
        generation = _canonical_uuid_text(
            generation,
            label="stateless runtime creation generation",
        )
        if type(attempted) is not bool:
            return False
        expected_runtime = None
        if expected_runtime_incarnation is not None:
            expected_runtime = _canonical_uuid_text(
                expected_runtime_incarnation,
                label="stateless workspace runtime incarnation",
            )
        async with self.acquire() as conn:
            async with conn.transaction():
                row = await conn.fetchrow(
                    "SELECT status::text AS status, execution_lane, "
                    "runtime_generation, metadata "
                    "FROM threads WHERE id = $1 FOR UPDATE",
                    thread_uuid,
                )
                if row is None:
                    return False
                try:
                    _, _, runtime, marker = _stateless_runtime_creation_context(row)
                except RuntimeError:
                    return False
                return bool(
                    runtime == expected_runtime
                    and marker is not None
                    and marker["generation"] == generation
                    and marker["attempted"] is attempted
                )

    async def publish_stateless_thread_workspace_runtime(
        self,
        thread_id: str,
        *,
        generation: str,
        runtime_incarnation: str,
        pod_name: str,
        namespace: str,
        creation_reservation_id: str,
        creation_claim_token: int,
    ) -> bool:
        """Publish the exact Pod UID immediately after create/adoption."""

        try:
            thread_uuid = UUID(str(thread_id))
        except (TypeError, ValueError):
            return False
        generation = _canonical_uuid_text(
            generation,
            label="stateless runtime creation generation",
        )
        runtime_incarnation = _canonical_uuid_text(
            runtime_incarnation,
            label="stateless workspace runtime incarnation",
        )
        try:
            reservation_id = str(UUID(str(creation_reservation_id)))
        except (TypeError, ValueError):
            return False
        if (
            isinstance(creation_claim_token, bool)
            or not isinstance(creation_claim_token, int)
            or creation_claim_token <= 0
        ):
            return False
        if not isinstance(pod_name, str) or not pod_name:
            raise ValueError("workspace pod name is invalid")
        if not isinstance(namespace, str) or not namespace:
            raise ValueError("workspace namespace is invalid")

        async with self.acquire() as conn:
            async with conn.transaction():
                row = await conn.fetchrow(
                    "SELECT status::text AS status, execution_lane, "
                    "runtime_generation, metadata "
                    "FROM threads WHERE id = $1 FOR UPDATE",
                    thread_uuid,
                )
                if row is None:
                    return False
                try:
                    metadata, workspace, current_runtime, marker = (
                        _stateless_runtime_creation_context(row)
                    )
                except RuntimeError:
                    return False
                if (
                    marker is None
                    or marker["generation"] != generation
                    or marker["attempted"] is not True
                    or current_runtime not in {None, runtime_incarnation}
                ):
                    return False
                workspace.update(
                    {
                        "status": "created",
                        "provisioner": "k8s",
                        "pod_name": pod_name,
                        "namespace": namespace,
                        _STATELESS_RUNTIME_INCARNATION_KEY: runtime_incarnation,
                        "_creation_reservation_id": reservation_id,
                        "_creation_claim_token": str(creation_claim_token),
                        _STATELESS_WORKSPACE_GENERATION_KEY: None,
                    }
                )
                workspace[_STATELESS_RUNTIME_CREATION_KEY] = _persisted_creation_marker(
                    marker
                )
                metadata["workspace_container"] = workspace
                result = await conn.execute(
                    "UPDATE threads SET metadata = $2::jsonb, "
                    "last_activity = CURRENT_TIMESTAMP WHERE id = $1",
                    thread_uuid,
                    json.dumps(metadata),
                )
                return result == "UPDATE 1"

    async def clear_stateless_thread_workspace_runtime_for_recreation(
        self,
        thread_id: str,
        *,
        generation: str,
        expected_runtime_incarnation: str,
    ) -> bool:
        """Expose a prepared create only after the proven terminal UID is gone."""

        try:
            thread_uuid = UUID(str(thread_id))
        except (TypeError, ValueError):
            return False
        generation = _canonical_uuid_text(
            generation,
            label="stateless runtime creation generation",
        )
        expected_runtime = _canonical_uuid_text(
            expected_runtime_incarnation,
            label="stateless workspace runtime incarnation",
        )
        async with self.acquire() as conn:
            async with conn.transaction():
                row = await conn.fetchrow(
                    "SELECT status::text AS status, execution_lane, "
                    "runtime_generation, metadata "
                    "FROM threads WHERE id = $1 FOR UPDATE",
                    thread_uuid,
                )
                if row is None:
                    return False
                try:
                    metadata, workspace, runtime, marker = (
                        _stateless_runtime_creation_context(row)
                    )
                except RuntimeError:
                    return False
                if (
                    runtime is None
                    and str(workspace.get("status") or "") == "deleted"
                    and marker is not None
                    and marker["generation"] == generation
                    and marker["attempted"] is False
                    and marker["replaces_uid"] == expected_runtime
                    and bool(
                        await conn.fetchval(
                            "SELECT managed_repository_workspace_cleanup_projection_is_settled("
                            "'thread', $1, 'workspace_container', $2, NULL, 'deleted')",
                            thread_uuid,
                            expected_runtime,
                        )
                    )
                ):
                    return True
                if (
                    runtime != expected_runtime
                    or marker is None
                    or marker["generation"] != generation
                    or marker["attempted"] is not False
                    or marker["replaces_uid"] != expected_runtime
                ):
                    return False
                workspace.update(
                    {
                        "status": "deleted",
                        "pod_ip": None,
                        _STATELESS_RUNTIME_INCARNATION_KEY: None,
                    }
                )
                workspace[_STATELESS_RUNTIME_CREATION_KEY] = _persisted_creation_marker(
                    marker
                )
                metadata["workspace_container"] = workspace
                result = await conn.execute(
                    "UPDATE threads SET metadata = $2::jsonb, "
                    "last_activity = CURRENT_TIMESTAMP WHERE id = $1",
                    thread_uuid,
                    json.dumps(metadata),
                )
                return result == "UPDATE 1"

    async def complete_stateless_thread_workspace_creation(
        self,
        thread_id: str,
        *,
        generation: str,
        runtime_incarnation: str,
        backing_id: str,
        ssh_host_key_fingerprint: str,
        pod_ip: str,
        port: int,
        creation_reservation_id: str,
        creation_claim_token: int,
        host: str | None = None,
    ) -> dict[str, Any] | None:
        """Atomically bind and publish Ready for the exact create authority."""

        try:
            thread_uuid = UUID(str(thread_id))
        except (TypeError, ValueError):
            return None
        generation = _canonical_uuid_text(
            generation,
            label="stateless runtime creation generation",
        )
        runtime_incarnation = _canonical_uuid_text(
            runtime_incarnation,
            label="stateless workspace runtime incarnation",
        )
        try:
            reservation_id = str(UUID(str(creation_reservation_id)))
        except (TypeError, ValueError):
            return None
        if (
            isinstance(creation_claim_token, bool)
            or not isinstance(creation_claim_token, int)
            or creation_claim_token <= 0
        ):
            return None
        if (
            not isinstance(backing_id, str)
            or not backing_id.strip()
            or len(backing_id) > 512
            or "\x00" in backing_id
        ):
            raise ValueError("workspace backing id is invalid")
        if (
            not isinstance(ssh_host_key_fingerprint, str)
            or not ssh_host_key_fingerprint.startswith("SHA256:")
            or len(ssh_host_key_fingerprint) > 128
            or any(ch.isspace() for ch in ssh_host_key_fingerprint)
        ):
            raise ValueError("workspace host-key fingerprint is invalid")
        if not isinstance(pod_ip, str) or not pod_ip:
            raise ValueError("workspace pod IP is invalid")
        if (
            isinstance(port, bool)
            or not isinstance(port, int)
            or not 1 <= port <= 65535
        ):
            raise ValueError("workspace SSH port is invalid")
        if host is not None and (not isinstance(host, str) or not host):
            raise ValueError("workspace host is invalid")

        async with self.acquire() as conn:
            async with conn.transaction():
                row = await conn.fetchrow(
                    "SELECT status::text AS status, execution_lane, "
                    "runtime_generation, metadata "
                    "FROM threads WHERE id = $1 FOR UPDATE",
                    thread_uuid,
                )
                if row is None:
                    return None
                try:
                    metadata, workspace, current_runtime, marker = (
                        _stateless_runtime_creation_context(row)
                    )
                except RuntimeError:
                    return None
                if (
                    marker is None
                    or marker["generation"] != generation
                    or marker["attempted"] is not True
                    or current_runtime != runtime_incarnation
                    or workspace.get("_creation_reservation_id") != reservation_id
                    or workspace.get("_creation_claim_token")
                    != str(creation_claim_token)
                ):
                    return None

                binding = metadata.get("_workspace_binding")
                if binding is not None and not isinstance(binding, dict):
                    return None
                binding = dict(binding or {})
                old_generation = binding.get("generation")
                try:
                    old_generation = _canonical_uuid_text(
                        old_generation, label="workspace binding generation"
                    )
                except RuntimeError:
                    old_generation = None
                unchanged = (
                    old_generation is not None
                    and binding.get("kind") == "remote"
                    and binding.get("backing_id") == backing_id
                    and binding.get("ssh_host_key_fingerprint")
                    == ssh_host_key_fingerprint
                )
                workspace_generation = old_generation if unchanged else str(uuid4())
                metadata["_workspace_binding"] = {
                    "generation": workspace_generation,
                    "kind": "remote",
                    "backing_id": backing_id,
                    "ssh_host_key_fingerprint": ssh_host_key_fingerprint,
                }
                workspace.update(
                    {
                        "status": "ready",
                        "provisioner": "k8s",
                        "pod_ip": pod_ip,
                        "port": port,
                        _STATELESS_WORKSPACE_GENERATION_KEY: workspace_generation,
                        _STATELESS_RUNTIME_INCARNATION_KEY: runtime_incarnation,
                        "_creation_reservation_id": reservation_id,
                        "_creation_claim_token": str(creation_claim_token),
                    }
                )
                if host is not None:
                    workspace["host"] = host
                else:
                    workspace.pop("host", None)
                workspace.pop(_STATELESS_RUNTIME_CREATION_KEY, None)
                workspace.pop("error", None)
                metadata["workspace_container"] = workspace
                result = await conn.execute(
                    "UPDATE threads SET metadata = $2::jsonb, "
                    "last_activity = CURRENT_TIMESTAMP WHERE id = $1",
                    thread_uuid,
                    json.dumps(metadata),
                )
                if result != "UPDATE 1":
                    return None
                return {
                    "workspace_generation": workspace_generation,
                    "runtime_incarnation": runtime_incarnation,
                }

    async def bind_thread_workspace_backing(
        self,
        thread_id: str,
        *,
        backing_kind: str,
        backing_id: str,
        ssh_host_key_fingerprint: str | None = None,
    ) -> dict[str, Any] | None:
        """Atomically bind a thread to one concrete workspace generation.

        Ordinary status/endpoint merges deliberately do not touch this
        identity. Repeating the same binding is a no-op; a different backing
        identifier, kind, or pinned SSH host key mints a new opaque generation.
        This keeps generation and fingerprint paired under one row lock.
        """

        try:
            uuid_val = UUID(thread_id)
        except ValueError:
            return None
        if backing_kind not in {"remote", "virtual"}:
            raise ValueError("workspace backing kind must be remote or virtual")
        backing_id = str(backing_id).strip()
        if not backing_id or len(backing_id) > 512 or "\x00" in backing_id:
            raise ValueError("workspace backing id is invalid")
        if backing_kind == "remote" and not ssh_host_key_fingerprint:
            raise ValueError("remote workspace binding requires a host fingerprint")
        if ssh_host_key_fingerprint is not None:
            ssh_host_key_fingerprint = ssh_host_key_fingerprint.strip()
            if (
                not ssh_host_key_fingerprint.startswith("SHA256:")
                or len(ssh_host_key_fingerprint) > 128
                or any(ch.isspace() for ch in ssh_host_key_fingerprint)
            ):
                raise ValueError("SSH host-key fingerprint is invalid")

        async with self.acquire() as conn:
            async with conn.transaction():
                row = await conn.fetchrow(
                    "SELECT metadata FROM threads WHERE id = $1 FOR UPDATE",
                    uuid_val,
                )
                if row is None:
                    return None
                metadata = row.get("metadata") or {}
                if isinstance(metadata, str):
                    try:
                        metadata = json.loads(metadata)
                    except (TypeError, ValueError):
                        metadata = {}
                if not isinstance(metadata, dict):
                    metadata = {}

                binding = metadata.get("_workspace_binding") or {}
                if not isinstance(binding, dict):
                    binding = {}
                generation = binding.get("generation")
                valid_generation = False
                try:
                    UUID(str(generation))
                    valid_generation = True
                except (TypeError, ValueError):
                    pass
                unchanged = (
                    valid_generation
                    and binding.get("kind") == backing_kind
                    and binding.get("backing_id") == backing_id
                    and binding.get("ssh_host_key_fingerprint")
                    == ssh_host_key_fingerprint
                )
                if unchanged:
                    return {
                        "workspace_generation": str(generation),
                        "changed": False,
                    }

                generation = str(uuid4())
                patch = {
                    "_workspace_binding": {
                        "generation": generation,
                        "kind": backing_kind,
                        "backing_id": backing_id,
                        "ssh_host_key_fingerprint": ssh_host_key_fingerprint,
                    }
                }
                await conn.execute(
                    """
                    UPDATE threads
                    SET metadata = COALESCE(metadata, '{}'::jsonb) || $2::jsonb,
                        last_activity = CURRENT_TIMESTAMP
                    WHERE id = $1
                    """,
                    uuid_val,
                    json.dumps(patch),
                )
                return {"workspace_generation": generation, "changed": True}

    async def reserve_pinned_thread_workspace_provision_intent(
        self,
        thread_id: str,
        *,
        expected_runtime_generation: str,
        expected_agent_id: str | None,
        expected_attach_token: str | None,
        expected_workspace_context: Mapping[str, Any] | None,
        expected_binding_context: Mapping[str, Any] | None,
        attempt_id: str,
        namespace: str,
        pod_name: str,
        pvc_name: str | None,
        seed_configmap_name: str | None,
        service_name: str | None,
        retained_service_uid: str | None,
        network_tier: str,
        manifest_fingerprint: str,
    ) -> Dict[str, Any] | None:
        """Durably name every pinned Kubernetes create before its first effect.

        The row lock is the lifecycle admission edge.  A route read made before
        End, Resume, actor rebind, or another workspace publication cannot
        install an intent afterwards.  Retries adopt the sole exact planned
        attempt and therefore never issue a second set of names.
        """

        def _dns_name(value: object, *, optional: bool = False) -> str | None:
            if optional and value is None:
                return None
            candidate = str(value or "").strip()
            if (
                not candidate
                or len(candidate) > 253
                or re.fullmatch(r"[a-z0-9](?:[-a-z0-9.]*[a-z0-9])?", candidate) is None
            ):
                raise ValueError("invalid Kubernetes resource name")
            return candidate

        try:
            parsed_thread = UUID(str(thread_id))
            parsed_generation = UUID(str(expected_runtime_generation))
            parsed_attempt = UUID(str(attempt_id))
            parsed_agent = (
                UUID(str(expected_agent_id)) if expected_agent_id is not None else None
            )
            parsed_attach = (
                UUID(str(expected_attach_token))
                if expected_attach_token is not None
                else None
            )
            parsed_namespace = _dns_name(namespace)
            parsed_pod_name = _dns_name(pod_name)
            parsed_pvc_name = _dns_name(pvc_name, optional=True)
            parsed_seed_name = _dns_name(seed_configmap_name, optional=True)
            parsed_service_name = _dns_name(service_name, optional=True)
        except (TypeError, ValueError):
            return None
        if (
            (parsed_agent is None) != (parsed_attach is None)
            or (parsed_pvc_name is None) != (parsed_service_name is None)
            or (retained_service_uid is not None and parsed_service_name is None)
            or not isinstance(network_tier, str)
            or not network_tier.strip()
            or len(network_tier.strip()) > 32
            or not isinstance(manifest_fingerprint, str)
            or re.fullmatch(r"[0-9a-f]{64}", manifest_fingerprint) is None
            or expected_workspace_context is not None
            and not isinstance(expected_workspace_context, Mapping)
            or expected_binding_context is not None
            and not isinstance(expected_binding_context, Mapping)
        ):
            return None
        expected_workspace = (
            dict(expected_workspace_context)
            if expected_workspace_context is not None
            else None
        )
        expected_binding = (
            dict(expected_binding_context)
            if expected_binding_context is not None
            else None
        )

        async with self.acquire() as conn:
            async with conn.transaction():
                row = await conn.fetchrow(
                    "SELECT status,execution_lane,runtime_generation,"
                    "runtime_retirement_token,agent_id,runtime_attach_token,metadata "
                    "FROM threads WHERE id=$1::uuid FOR UPDATE",
                    parsed_thread,
                )
                if row is None:
                    return None
                metadata = row["metadata"]
                if isinstance(metadata, str):
                    try:
                        metadata = json.loads(metadata)
                    except (TypeError, ValueError):
                        return None
                if not isinstance(metadata, dict):
                    return None
                raw_workspace = metadata.get("workspace_container")
                raw_binding = metadata.get("_workspace_binding")
                raw_vm = metadata.get("vm")
                if not all(
                    value is None or isinstance(value, dict)
                    for value in (raw_workspace, raw_binding, raw_vm)
                ):
                    return None
                current_workspace = (
                    dict(raw_workspace) if raw_workspace is not None else None
                )
                current_binding = dict(raw_binding) if raw_binding is not None else None
                current_vm = dict(raw_vm) if raw_vm is not None else {}
                if not (
                    str(row["execution_lane"] or "") == "pinned"
                    and str(row["status"] or "")
                    in {"created", "active", "awaiting_user", "suspended"}
                    and row["runtime_generation"] == parsed_generation
                    and row["runtime_retirement_token"] is None
                    and row["agent_id"] == parsed_agent
                    and row["runtime_attach_token"] == parsed_attach
                ):
                    return None
                inverse = await conn.fetch(
                    "SELECT id FROM agents WHERE thread_id=$1::uuid FOR SHARE",
                    parsed_thread,
                )
                if parsed_agent is None:
                    if inverse:
                        return None
                elif len(inverse) != 1 or inverse[0]["id"] != parsed_agent:
                    return None

                existing = await conn.fetchrow(
                    "SELECT * FROM thread_workspace_provision_intents "
                    "WHERE thread_id=$1::uuid "
                    "AND status IN ('planned','revoking','fenced') FOR UPDATE",
                    parsed_thread,
                )
                if existing is not None:
                    marker = current_workspace or {}
                    if not (
                        str(existing["status"]) == "planned"
                        and str(existing["runtime_generation"])
                        == str(parsed_generation)
                        and existing["created_agent_id"] == parsed_agent
                        and existing["created_attach_token"] == parsed_attach
                        and str(existing["namespace"]) == parsed_namespace
                        and str(existing["pod_name"]) == parsed_pod_name
                        and existing["pvc_name"] == parsed_pvc_name
                        and existing["seed_configmap_name"] == parsed_seed_name
                        and existing["service_name"] == parsed_service_name
                        and str(existing["retained_service_uid"] or "")
                        == str(retained_service_uid or "").strip()
                        and str(existing["network_tier"]) == network_tier.strip()
                        and str(existing["manifest_fingerprint"])
                        == manifest_fingerprint
                        and isinstance(marker, dict)
                        and str(marker.get("_workspace_provision_attempt") or "")
                        == str(existing["attempt_id"])
                        and str(marker.get("_workspace_provision_generation") or "")
                        == str(parsed_generation)
                    ):
                        return None
                    return dict(existing)

                if (
                    current_workspace != expected_workspace
                    or current_binding != expected_binding
                ):
                    return None
                workspace = current_workspace or {}
                allowed_status = workspace.get("status")
                if not (
                    allowed_status is None
                    or isinstance(allowed_status, str)
                    and allowed_status in {"", "deleted", "failed", "suspended"}
                ):
                    return None
                if any(
                    _json_field_is_nonnull(workspace, field)
                    for field in (
                        "_runtime_incarnation",
                        "_docker_workspace_lease_id",
                        "pod_ip",
                        "pod_name",
                        "host",
                        "port",
                        "ide_host",
                        "ide_port",
                        "_canvas_workspace_generation",
                    )
                ):
                    predecessor_generation = (
                        await _settled_pinned_workspace_predecessor_generation(
                            conn,
                            thread_id=parsed_thread,
                            current_generation=parsed_generation,
                            workspace=workspace,
                            binding=current_binding or {},
                            namespace=parsed_namespace,
                            pod_name=parsed_pod_name,
                            pvc_name=parsed_pvc_name,
                        )
                    )
                    if predecessor_generation is None:
                        return None
                if not _json_runtime_status_is_absent(current_vm) or any(
                    _json_field_is_nonnull(current_vm, field)
                    for field in (
                        "provision_generation",
                        "identity_provision_generation",
                        "vm_uid",
                        "_runtime_incarnation",
                        "rootdisk_pvc_uid",
                        "ssh_host",
                        "ssh_port",
                        "_canvas_workspace_generation",
                    )
                ):
                    return None

                previous_binding = current_binding or {}
                retained_generation: UUID | None = None
                retained_pvc_uid: str | None = None
                if previous_binding:
                    kind = previous_binding.get("kind")
                    backing_id = str(previous_binding.get("backing_id") or "")
                    if kind == "virtual":
                        if re.fullmatch(r"rclone:[0-9a-f]{64}", backing_id) is None:
                            return None
                        try:
                            UUID(str(previous_binding.get("generation") or ""))
                        except (TypeError, ValueError):
                            return None
                    elif kind == "remote" and backing_id.startswith(
                        f"k8s-pvc:{parsed_namespace}:"
                    ):
                        if parsed_pvc_name is None:
                            return None
                        try:
                            retained_generation = UUID(
                                str(previous_binding.get("generation") or "")
                            )
                            retained_pvc_uid = str(UUID(backing_id.rsplit(":", 1)[-1]))
                        except (TypeError, ValueError):
                            return None
                    elif kind == "remote" and backing_id.startswith(
                        f"k8s-pod:{parsed_namespace}:"
                    ):
                        try:
                            UUID(str(previous_binding.get("generation") or ""))
                            UUID(backing_id.rsplit(":", 1)[-1])
                        except (TypeError, ValueError):
                            return None
                    else:
                        return None

                intent = await conn.fetchrow(
                    "INSERT INTO thread_workspace_provision_intents ("
                    "attempt_id,thread_id,runtime_generation,created_agent_id,"
                    "created_attach_token,namespace,pod_name,pvc_name,"
                    "seed_configmap_name,service_name,network_tier,"
                    "manifest_fingerprint,"
                    "previous_binding,retained_binding_generation,retained_pvc_uid,"
                    "retained_service_uid) "
                    "VALUES ($1::uuid,$2::uuid,$3::uuid,$4::uuid,$5::uuid,"
                    "$6,$7,$8,$9,$10,$11,$12,$13::jsonb,$14::uuid,$15,$16) "
                    "RETURNING *",
                    parsed_attempt,
                    parsed_thread,
                    parsed_generation,
                    parsed_agent,
                    parsed_attach,
                    parsed_namespace,
                    parsed_pod_name,
                    parsed_pvc_name,
                    parsed_seed_name,
                    parsed_service_name,
                    network_tier.strip(),
                    manifest_fingerprint,
                    json.dumps(previous_binding, sort_keys=True, separators=(",", ":")),
                    retained_generation,
                    retained_pvc_uid,
                    str(retained_service_uid or "").strip() or None,
                )
                pending = dict(workspace)
                pending.update(
                    {
                        "status": "pending",
                        "provisioner": "k8s",
                        "_workspace_provision_attempt": str(parsed_attempt),
                        "_workspace_provision_generation": str(parsed_generation),
                        "_runtime_incarnation": None,
                        "_canvas_workspace_generation": None,
                        "pod_ip": None,
                        "pod_name": None,
                        "host": None,
                        "port": None,
                        "ide_host": None,
                        "ide_port": None,
                    }
                )
                updated_metadata = dict(metadata)
                updated_metadata["workspace_container"] = pending
                result = await conn.execute(
                    "UPDATE threads SET metadata=$4::jsonb,last_activity=now() "
                    "WHERE id=$1::uuid AND runtime_generation=$2::uuid "
                    "AND runtime_retirement_token IS NULL "
                    "AND metadata IS NOT DISTINCT FROM $3::jsonb",
                    parsed_thread,
                    parsed_generation,
                    json.dumps(metadata, sort_keys=True, separators=(",", ":")),
                    json.dumps(updated_metadata, sort_keys=True, separators=(",", ":")),
                )
                if result != "UPDATE 1":
                    raise RuntimeError("workspace provision intent publication lost")
                return dict(intent)

    async def publish_pinned_thread_workspace_provision_resource(
        self,
        thread_id: str,
        *,
        expected_runtime_generation: str,
        attempt_id: str,
        resource: str,
        resource_uid: str,
    ) -> bool:
        """Record one exact original Kubernetes UID under a planned intent."""

        columns = {
            "pod": ("pod_uid", "pod_name"),
            "pvc": ("pvc_uid", "pvc_name"),
            "seed_configmap": ("seed_configmap_uid", "seed_configmap_name"),
            "service": ("service_uid", "service_name"),
        }
        selected = columns.get(resource)
        uid = str(resource_uid or "").strip()
        if selected is None or not uid:
            return False
        try:
            parsed_thread = UUID(str(thread_id))
            parsed_generation = UUID(str(expected_runtime_generation))
            parsed_attempt = UUID(str(attempt_id))
        except (TypeError, ValueError):
            return False
        uid_column, name_column = selected
        async with self.acquire() as conn:
            async with conn.transaction():
                thread = await conn.fetchrow(
                    "SELECT execution_lane,status,runtime_generation,"
                    "runtime_retirement_token,agent_id,runtime_attach_token,metadata "
                    "FROM threads WHERE id=$1::uuid FOR UPDATE",
                    parsed_thread,
                )
                intent = await conn.fetchrow(
                    "SELECT * FROM thread_workspace_provision_intents "
                    "WHERE attempt_id=$1::uuid AND thread_id=$2::uuid FOR UPDATE",
                    parsed_attempt,
                    parsed_thread,
                )
                if intent is None or thread is None:
                    return False
                metadata = thread["metadata"]
                if isinstance(metadata, str):
                    try:
                        metadata = json.loads(metadata)
                    except (TypeError, ValueError):
                        return False
                workspace = (
                    metadata.get("workspace_container")
                    if isinstance(metadata, dict)
                    else None
                )
                if not (
                    str(intent["status"]) == "planned"
                    and str(intent["runtime_generation"]) == str(parsed_generation)
                    and intent[name_column] is not None
                    and str(thread["execution_lane"] or "") == "pinned"
                    and str(thread["status"] or "")
                    in {"created", "active", "awaiting_user", "suspended"}
                    and thread["runtime_generation"] == parsed_generation
                    and thread["runtime_retirement_token"] is None
                    and thread["agent_id"] == intent["created_agent_id"]
                    and thread["runtime_attach_token"] == intent["created_attach_token"]
                    and isinstance(workspace, dict)
                    and str(workspace.get("_workspace_provision_attempt") or "")
                    == str(parsed_attempt)
                    and str(workspace.get("_workspace_provision_generation") or "")
                    == str(parsed_generation)
                ):
                    return False
                current_uid = intent[uid_column]
                if current_uid is not None:
                    return str(current_uid) == uid
                if resource == "pvc" and intent["retained_pvc_uid"] is not None:
                    if str(intent["retained_pvc_uid"]) != uid:
                        return False
                result = await conn.execute(
                    f"UPDATE thread_workspace_provision_intents SET {uid_column}=$2 "
                    "WHERE attempt_id=$1::uuid AND status='planned' "
                    f"AND {uid_column} IS NULL",
                    parsed_attempt,
                    uid,
                )
                return result == "UPDATE 1"

    async def complete_pinned_thread_workspace_provision_intent(
        self,
        thread_id: str,
        *,
        expected_runtime_generation: str,
        attempt_id: str,
        expected_pod_uid: str,
        expected_pvc_uid: str | None,
        expected_seed_configmap_uid: str | None,
        expected_service_uid: str | None,
        pod_ip: str,
        ssh_host_key_fingerprint: str,
        port: int = 30022,
    ) -> Dict[str, Any] | None:
        """Publish Ready + backing from one fully observed workspace attempt."""

        if (
            not isinstance(pod_ip, str)
            or not pod_ip.strip()
            or not isinstance(ssh_host_key_fingerprint, str)
            or re.fullmatch(r"SHA256:[A-Za-z0-9+/]{43}", ssh_host_key_fingerprint)
            is None
            or isinstance(port, bool)
            or not isinstance(port, int)
            or not 1 <= port <= 65535
        ):
            return None
        try:
            parsed_thread = UUID(str(thread_id))
            parsed_generation = UUID(str(expected_runtime_generation))
            parsed_attempt = UUID(str(attempt_id))
            parsed_pod_uid = UUID(str(expected_pod_uid))
            parsed_pvc_uid = (
                UUID(str(expected_pvc_uid)) if expected_pvc_uid is not None else None
            )
            parsed_seed_uid = (
                UUID(str(expected_seed_configmap_uid))
                if expected_seed_configmap_uid is not None
                else None
            )
            parsed_service_uid = (
                UUID(str(expected_service_uid))
                if expected_service_uid is not None
                else None
            )
        except (TypeError, ValueError):
            return None
        async with self.acquire() as conn:
            async with conn.transaction():
                thread = await conn.fetchrow(
                    "SELECT execution_lane,status,runtime_generation,"
                    "runtime_retirement_token,agent_id,runtime_attach_token,metadata "
                    "FROM threads WHERE id=$1::uuid FOR UPDATE",
                    parsed_thread,
                )
                intent = await conn.fetchrow(
                    "SELECT * FROM thread_workspace_provision_intents "
                    "WHERE attempt_id=$1::uuid AND thread_id=$2::uuid FOR UPDATE",
                    parsed_attempt,
                    parsed_thread,
                )
                if intent is None or thread is None:
                    return None
                metadata = thread["metadata"]
                if isinstance(metadata, str):
                    try:
                        metadata = json.loads(metadata)
                    except (TypeError, ValueError):
                        return None
                if not isinstance(metadata, dict):
                    return None
                workspace = metadata.get("workspace_container")
                current_binding = metadata.get("_workspace_binding")
                current_binding = {} if current_binding is None else current_binding
                try:
                    previous_binding = _strict_json_object(
                        intent["previous_binding"],
                        label="workspace provision intent previous binding",
                    )
                except RuntimeError:
                    return None
                if not (
                    str(intent["status"]) == "planned"
                    and str(intent["runtime_generation"]) == str(parsed_generation)
                    and str(intent["pod_uid"] or "") == str(parsed_pod_uid)
                    and (
                        intent["pvc_uid"] is None
                        if parsed_pvc_uid is None
                        else str(intent["pvc_uid"] or "") == str(parsed_pvc_uid)
                    )
                    and (intent["pvc_name"] is None) == (parsed_pvc_uid is None)
                    and (
                        intent["seed_configmap_uid"] is None
                        if parsed_seed_uid is None
                        else str(intent["seed_configmap_uid"] or "")
                        == str(parsed_seed_uid)
                    )
                    and (intent["seed_configmap_name"] is None)
                    == (parsed_seed_uid is None)
                    and (
                        intent["service_uid"] is None
                        if parsed_service_uid is None
                        else str(intent["service_uid"] or "") == str(parsed_service_uid)
                    )
                    and (intent["service_name"] is None) == (parsed_service_uid is None)
                    and str(thread["execution_lane"] or "") == "pinned"
                    and str(thread["status"] or "")
                    in {"created", "active", "awaiting_user", "suspended"}
                    and thread["runtime_generation"] == parsed_generation
                    and thread["runtime_retirement_token"] is None
                    and thread["agent_id"] == intent["created_agent_id"]
                    and thread["runtime_attach_token"] == intent["created_attach_token"]
                    and isinstance(workspace, dict)
                    and str(workspace.get("_workspace_provision_attempt") or "")
                    == str(parsed_attempt)
                    and str(workspace.get("_workspace_provision_generation") or "")
                    == str(parsed_generation)
                    and isinstance(current_binding, dict)
                    and current_binding == previous_binding
                ):
                    return None
                pod_uid = str(intent["pod_uid"])
                pvc_uid = str(intent["pvc_uid"] or "") or None
                backing_id = (
                    f"k8s-pvc:{intent['namespace']}:{pvc_uid}"
                    if pvc_uid is not None
                    else f"k8s-pod:{intent['namespace']}:{pod_uid}"
                )
                previous = previous_binding
                if (
                    intent["retained_binding_generation"] is not None
                    and str(intent["retained_pvc_uid"] or "") == str(pvc_uid or "")
                    and str(previous.get("backing_id") or "") == backing_id
                    and previous.get("kind") == "remote"
                ):
                    binding_generation = str(intent["retained_binding_generation"])
                else:
                    binding_generation = str(uuid4())
                binding = {
                    "generation": binding_generation,
                    "kind": "remote",
                    "backing_id": backing_id,
                    "ssh_host_key_fingerprint": ssh_host_key_fingerprint,
                }
                ready = dict(workspace)
                ready.pop("_workspace_provision_attempt", None)
                ready.pop("_workspace_provision_generation", None)
                ready.update(
                    {
                        "status": "ready",
                        "provisioner": "k8s",
                        "pod_name": str(intent["pod_name"]),
                        "namespace": str(intent["namespace"]),
                        "pod_ip": pod_ip.strip(),
                        "port": port,
                        "host": (
                            f"{intent['service_name']}.{intent['namespace']}.svc.cluster.local"
                            if intent["service_name"] is not None
                            else None
                        ),
                        "_runtime_incarnation": pod_uid,
                        "_canvas_workspace_generation": binding_generation,
                    }
                )
                updated_metadata = dict(metadata)
                updated_metadata["workspace_container"] = ready
                updated_metadata["_workspace_binding"] = binding
                updated = await conn.execute(
                    "UPDATE threads SET metadata=$4::jsonb,last_activity=now() "
                    "WHERE id=$1::uuid AND runtime_generation=$2::uuid "
                    "AND runtime_retirement_token IS NULL "
                    "AND metadata IS NOT DISTINCT FROM $3::jsonb",
                    parsed_thread,
                    parsed_generation,
                    json.dumps(metadata, sort_keys=True, separators=(",", ":")),
                    json.dumps(updated_metadata, sort_keys=True, separators=(",", ":")),
                )
                if updated != "UPDATE 1":
                    raise RuntimeError("workspace Ready publication lost")
                resolved = await conn.execute(
                    "UPDATE thread_workspace_provision_intents "
                    "SET status='published',resolved_at=now() "
                    "WHERE attempt_id=$1::uuid AND status='planned'",
                    parsed_attempt,
                )
                if resolved != "UPDATE 1":
                    raise RuntimeError("workspace intent resolution lost")
                return {
                    "runtime_incarnation": pod_uid,
                    "workspace_generation": binding_generation,
                    "backing_id": backing_id,
                    "host": ready.get("host"),
                }

    async def revoke_pinned_thread_workspace_provision_intent(
        self,
        thread_id: str,
        *,
        expected_runtime_generation: str,
        expected_retirement_token: str,
        expected_attempt_id: str,
    ) -> Dict[str, Any] | None:
        """Close a planned multi-object create before acquiring name fences."""

        try:
            parsed_thread = UUID(str(thread_id))
            parsed_generation = UUID(str(expected_runtime_generation))
            parsed_retirement = UUID(str(expected_retirement_token))
            parsed_attempt = UUID(str(expected_attempt_id))
        except (TypeError, ValueError):
            return None
        async with self.acquire() as conn:
            async with conn.transaction():
                row = await conn.fetchrow(
                    "SELECT runtime_retirement_context FROM threads "
                    "WHERE id=$1::uuid AND execution_lane='pinned' "
                    "AND runtime_generation=$2::uuid "
                    "AND runtime_retirement_token=$3::uuid "
                    "AND runtime_retirement_authorized_at IS NOT NULL FOR UPDATE",
                    parsed_thread,
                    parsed_generation,
                    parsed_retirement,
                )
                intent = await conn.fetchrow(
                    "SELECT * FROM thread_workspace_provision_intents "
                    "WHERE attempt_id=$1::uuid AND thread_id=$2::uuid FOR UPDATE",
                    parsed_attempt,
                    parsed_thread,
                )
                if row is None or intent is None:
                    return None
                context = row["runtime_retirement_context"]
                if isinstance(context, str):
                    try:
                        context = json.loads(context)
                    except (TypeError, ValueError):
                        return None
                captured = (
                    context.get("workspace_provision_intent")
                    if isinstance(context, dict)
                    else None
                )
                if not (
                    isinstance(captured, dict)
                    and str(captured.get("attempt_id") or "") == str(parsed_attempt)
                    and str(captured.get("runtime_generation") or "")
                    == str(parsed_generation)
                    and str(intent["runtime_generation"]) == str(parsed_generation)
                ):
                    return None
                if str(intent["status"]) in {"revoking", "fenced", "retired"}:
                    return dict(intent)
                if str(intent["status"]) != "planned":
                    return None
                changed = await conn.execute(
                    "UPDATE thread_workspace_provision_intents "
                    "SET status='revoking' "
                    "WHERE attempt_id=$1::uuid AND status='planned'",
                    parsed_attempt,
                )
                if changed != "UPDATE 1":
                    raise RuntimeError("workspace intent revocation lost")
                refreshed = dict(intent)
                refreshed["status"] = "revoking"
                return refreshed

    async def fence_pinned_thread_workspace_provision_intent(
        self,
        thread_id: str,
        *,
        expected_runtime_generation: str,
        expected_retirement_token: str,
        expected_attempt_id: str,
        fence_pod_uid: str,
        fence_pvc_uid: str | None,
        fence_configmap_uid: str | None,
        fence_service_uid: str | None,
        permanent: bool,
    ) -> bool:
        """Persist same-name fences under the exact retirement snapshot.

        Soft retirement clears only the pending endpoint marker and preserves
        the captured prior backing. Permanent retirement leaves the thread
        metadata untouched here: the separate physical-clear CAS publishes
        the append-once external receipt in the same UPDATE that removes that
        evidence. A permanent follow-up may monotonically add PVC/Service
        fences omitted by an earlier soft retirement.
        """

        try:
            parsed_thread = UUID(str(thread_id))
            parsed_generation = UUID(str(expected_runtime_generation))
            parsed_retirement = UUID(str(expected_retirement_token))
            parsed_attempt = UUID(str(expected_attempt_id))
        except (TypeError, ValueError):
            return False
        fences = {
            "fence_pod_uid": str(fence_pod_uid or "").strip() or None,
            "fence_pvc_uid": str(fence_pvc_uid or "").strip() or None,
            "fence_configmap_uid": (str(fence_configmap_uid or "").strip() or None),
            "fence_service_uid": str(fence_service_uid or "").strip() or None,
        }
        async with self.acquire() as conn:
            async with conn.transaction():
                row = await conn.fetchrow(
                    "SELECT metadata,runtime_retirement_context,"
                    "runtime_retirement_permanent FROM threads "
                    "WHERE id=$1::uuid AND execution_lane='pinned' "
                    "AND runtime_generation=$2::uuid "
                    "AND runtime_retirement_token=$3::uuid "
                    "AND runtime_retirement_authorized_at IS NOT NULL FOR UPDATE",
                    parsed_thread,
                    parsed_generation,
                    parsed_retirement,
                )
                intent = await conn.fetchrow(
                    "SELECT * FROM thread_workspace_provision_intents "
                    "WHERE attempt_id=$1::uuid AND thread_id=$2::uuid FOR UPDATE",
                    parsed_attempt,
                    parsed_thread,
                )
                if row is None or intent is None:
                    return False
                metadata = row["metadata"]
                context = row["runtime_retirement_context"]
                try:
                    if isinstance(metadata, str):
                        metadata = json.loads(metadata)
                    if isinstance(context, str):
                        context = json.loads(context)
                except (TypeError, ValueError):
                    return False
                captured = (
                    context.get("workspace_provision_intent")
                    if isinstance(context, dict)
                    else None
                )
                workspace = (
                    metadata.get("workspace_container")
                    if isinstance(metadata, dict)
                    else None
                )
                previous_binding = intent["previous_binding"]
                if isinstance(previous_binding, str):
                    try:
                        previous_binding = json.loads(previous_binding)
                    except (TypeError, ValueError):
                        return False
                intent_status = str(intent["status"])
                if not (
                    isinstance(metadata, dict)
                    and isinstance(captured, dict)
                    and str(captured.get("attempt_id") or "") == str(parsed_attempt)
                    and str(captured.get("runtime_generation") or "")
                    == str(parsed_generation)
                    and str(intent["runtime_generation"]) == str(parsed_generation)
                    and isinstance(previous_binding, dict)
                    and dict(captured.get("previous_binding") or {})
                    == dict(previous_binding)
                    and all(
                        str(intent[field] or "") == str(captured.get(field) or "")
                        for field in (
                            "thread_id",
                            "created_agent_id",
                            "created_attach_token",
                            "namespace",
                            "pod_name",
                            "pvc_name",
                            "seed_configmap_name",
                            "service_name",
                            "network_tier",
                            "manifest_fingerprint",
                            "retained_binding_generation",
                            "retained_pvc_uid",
                            "retained_service_uid",
                            "pod_uid",
                            "pvc_uid",
                            "seed_configmap_uid",
                            "service_uid",
                        )
                    )
                    and intent_status in {"revoking", "fenced", "retired"}
                    and isinstance(workspace, dict)
                    and bool(row["runtime_retirement_permanent"]) == bool(permanent)
                    and fences["fence_pod_uid"]
                    and (
                        intent["pvc_name"] is None
                        or (not permanent and intent["retained_pvc_uid"] is not None)
                        or intent_status == "retired"
                        or fences["fence_pvc_uid"]
                    )
                    and (
                        intent["seed_configmap_name"] is None
                        or fences["fence_configmap_uid"]
                    )
                    and (
                        intent["service_name"] is None
                        or (
                            not permanent and intent["retained_service_uid"] is not None
                        )
                        or intent_status == "retired"
                        or fences["fence_service_uid"]
                    )
                ):
                    return False

                if intent_status == "retired":
                    pass
                else:
                    # Existing fence identities are immutable. A permanent
                    # follow-up may fill only the retained-resource holes from
                    # a prior soft fence and restarts the request horizon.
                    if any(
                        intent[key] is not None and intent[key] != value
                        for key, value in fences.items()
                    ):
                        return False
                    if intent_status == "fenced":
                        if all(intent[key] == value for key, value in fences.items()):
                            pass
                        elif not permanent:
                            return False
                        else:
                            upgraded = await conn.execute(
                                "UPDATE thread_workspace_provision_intents SET "
                                "fence_pod_uid=COALESCE(fence_pod_uid,$2),"
                                "fence_pvc_uid=COALESCE(fence_pvc_uid,$3),"
                                "fence_configmap_uid="
                                "COALESCE(fence_configmap_uid,$4),"
                                "fence_service_uid=COALESCE(fence_service_uid,$5),"
                                "fenced_at=now(),gc_after=now()+"
                                "($6::double precision * interval '1 second') "
                                "WHERE attempt_id=$1::uuid AND status='fenced'",
                                parsed_attempt,
                                fences["fence_pod_uid"],
                                fences["fence_pvc_uid"],
                                fences["fence_configmap_uid"],
                                fences["fence_service_uid"],
                                float(PINNED_K8S_CREATE_FENCE_HORIZON_SECONDS),
                            )
                            if upgraded != "UPDATE 1":
                                raise RuntimeError(
                                    "workspace intent fence upgrade lost"
                                )
                    else:
                        fenced = await conn.execute(
                            "UPDATE thread_workspace_provision_intents SET "
                            "status='fenced',fence_pod_uid=$2,fence_pvc_uid=$3,"
                            "fence_configmap_uid=$4,fence_service_uid=$5,"
                            "fenced_at=now(),gc_after=now()+"
                            "($6::double precision * interval '1 second') "
                            "WHERE attempt_id=$1::uuid AND status='revoking'",
                            parsed_attempt,
                            fences["fence_pod_uid"],
                            fences["fence_pvc_uid"],
                            fences["fence_configmap_uid"],
                            fences["fence_service_uid"],
                            float(PINNED_K8S_CREATE_FENCE_HORIZON_SECONDS),
                        )
                        if fenced != "UPDATE 1":
                            raise RuntimeError(
                                "workspace intent fence publication lost"
                            )

                if not permanent:
                    binding_unchanged = dict(
                        metadata.get("_workspace_binding") or {}
                    ) == dict(previous_binding)
                    marker_matches = bool(
                        str(workspace.get("_workspace_provision_attempt") or "")
                        == str(parsed_attempt)
                        and str(workspace.get("_workspace_provision_generation") or "")
                        == str(parsed_generation)
                    )
                    if not binding_unchanged:
                        return False
                    if not marker_matches:
                        return bool(
                            intent_status in {"fenced", "retired"}
                            and workspace.get("status") == "deleted"
                            and "_workspace_provision_attempt" not in workspace
                            and "_workspace_provision_generation" not in workspace
                        )
                    cleared = dict(workspace)
                    cleared.pop("_workspace_provision_attempt", None)
                    cleared.pop("_workspace_provision_generation", None)
                    cleared.update(
                        {
                            "status": "deleted",
                            "pod_ip": None,
                            "pod_name": None,
                            "host": None,
                            "port": None,
                            "ide_host": None,
                            "ide_port": None,
                            "_runtime_incarnation": None,
                            "_canvas_workspace_generation": None,
                        }
                    )
                    updated_metadata = dict(metadata)
                    updated_metadata["workspace_container"] = cleared
                    updated = await conn.execute(
                        "UPDATE threads SET metadata=$4::jsonb,last_activity=now() "
                        "WHERE id=$1::uuid AND runtime_generation=$2::uuid "
                        "AND runtime_retirement_token=$3::uuid "
                        "AND metadata IS NOT DISTINCT FROM $5::jsonb",
                        parsed_thread,
                        parsed_generation,
                        parsed_retirement,
                        json.dumps(
                            updated_metadata,
                            sort_keys=True,
                            separators=(",", ":"),
                        ),
                        json.dumps(metadata, sort_keys=True, separators=(",", ":")),
                    )
                    if updated != "UPDATE 1":
                        raise RuntimeError("workspace pending marker cleanup lost")
                return True

    async def list_pinned_thread_workspace_provision_fences_for_gc(
        self, *, limit: int = 100
    ) -> List[Dict[str, Any]]:
        """Return exact workspace fence work whose request horizon elapsed."""

        async with self.acquire() as conn:
            rows = await conn.fetch(
                "SELECT * FROM thread_workspace_provision_intents "
                "WHERE status='fenced' AND gc_after <= now() "
                "ORDER BY gc_after,created_at LIMIT $1",
                max(1, min(int(limit), 1000)),
            )
        return [dict(row) for row in rows]

    async def retire_pinned_thread_workspace_provision_fence(
        self,
        attempt_id: str,
        *,
        expected_fence_pod_uid: str,
        expected_fence_pvc_uid: str | None,
        expected_fence_configmap_uid: str | None,
        expected_fence_service_uid: str | None,
    ) -> bool:
        """Mark a post-horizon fence retired after exact UID deletion."""

        try:
            parsed_attempt = UUID(str(attempt_id))
        except (TypeError, ValueError):
            return False
        expected = tuple(
            str(value or "").strip() or None
            for value in (
                expected_fence_pod_uid,
                expected_fence_pvc_uid,
                expected_fence_configmap_uid,
                expected_fence_service_uid,
            )
        )
        if expected[0] is None:
            return False
        async with self.acquire() as conn:
            return (
                await conn.execute(
                    "UPDATE thread_workspace_provision_intents "
                    "SET status='retired',resolved_at=now() "
                    "WHERE attempt_id=$1::uuid AND status='fenced' "
                    "AND gc_after <= now() "
                    "AND fence_pod_uid IS NOT DISTINCT FROM $2 "
                    "AND fence_pvc_uid IS NOT DISTINCT FROM $3 "
                    "AND fence_configmap_uid IS NOT DISTINCT FROM $4 "
                    "AND fence_service_uid IS NOT DISTINCT FROM $5",
                    parsed_attempt,
                    *expected,
                )
                == "UPDATE 1"
            )

    async def begin_pinned_thread_vm_provisioning(
        self,
        thread_id: str,
        *,
        expected_runtime_generation: str,
        expected_agent_id: str | None,
        expected_attach_token: str | None,
        expected_vm_context: Mapping[str, Any] | None,
        provision_context: Mapping[str, Any],
        poll: bool = False,
        preparation_only: bool = False,
        expected_preparation_context: Mapping[str, Any] | None = None,
    ) -> bool | dict:
        """Install one VM provision generation before any controller effect.

        The caller's earlier route/read snapshot is advisory.  This method is
        the effect admission boundary: it locks the thread, proves the exact
        open pinned ``(T, G, agent, attach)`` authority and the VM subdocument
        the caller observed, then publishes the new provision generation and
        ``provisioning`` status in the same update.  A stale upgrade therefore
        cannot dispatch after End, Resume, rebind, or another VM attempt.

        ``preparation_only`` instead returns a separate durable cache stage;
        it installs no physical VM authority and preserves an existing stage's
        deadline. VM admission then compares ``expected_preparation_context``
        before consuming that stage in the same transaction.

        ``None`` means the ``vm`` member was absent/JSON-null.  Present scalar
        or array values fail closed instead of being truthiness-coerced to an
        empty object.
        """

        try:
            parsed_thread = UUID(str(thread_id))
            parsed_runtime_generation = UUID(str(expected_runtime_generation))
            parsed_agent = (
                UUID(str(expected_agent_id)) if expected_agent_id is not None else None
            )
            parsed_attach = (
                UUID(str(expected_attach_token))
                if expected_attach_token is not None
                else None
            )
        except (TypeError, ValueError):
            return False
        if (parsed_agent is None) != (parsed_attach is None):
            return False
        if expected_vm_context is not None and not isinstance(
            expected_vm_context, Mapping
        ):
            return False
        if not isinstance(provision_context, Mapping):
            return False
        proposed = dict(provision_context)
        try:
            provision_generation = _canonical_uuid_text(
                proposed.get("provision_generation"),
                label="thread VM provision generation",
            )
        except RuntimeError:
            return False
        if (
            proposed.get("status") != "provisioning"
            or proposed.get("identity_authenticated") is not False
            or proposed.get("identity_provision_generation") is not None
            or proposed.get("vm_uid") is not None
            or proposed.get("_runtime_incarnation") is not None
            or proposed.get("rootdisk_pvc_uid") is not None
            or proposed.get("ssh_host") is not None
            or proposed.get("ssh_port") is not None
            or proposed.get("_canvas_workspace_generation") is not None
        ):
            return False
        proposed["provision_generation"] = provision_generation
        if preparation_only:
            from shared.workspace_preparation import validate_request

            try:
                preparation = validate_request(proposed["preparation_request"])
            except (ValueError, TypeError, KeyError):
                return False
            if (
                preparation["allocationId"] != str(parsed_thread)
                or preparation["ownerKind"] != "session"
                or preparation["runtimeGeneration"] != str(parsed_runtime_generation)
            ):
                return False
        expected_vm = (
            dict(expected_vm_context) if expected_vm_context is not None else None
        )

        async with self.acquire() as conn:
            async with conn.transaction():
                row = await conn.fetchrow(
                    "SELECT status,execution_lane,runtime_generation,"
                    "runtime_retirement_token,agent_id,runtime_attach_token,metadata "
                    "FROM threads WHERE id=$1::uuid FOR UPDATE",
                    parsed_thread,
                )
                if row is None:
                    return False
                metadata = row["metadata"]
                if isinstance(metadata, str):
                    try:
                        metadata = json.loads(metadata)
                    except (TypeError, ValueError):
                        return False
                if not isinstance(metadata, dict):
                    return False
                raw_current_vm = metadata.get("vm")
                if raw_current_vm is not None and not isinstance(raw_current_vm, dict):
                    return False
                current_vm = (
                    dict(raw_current_vm) if raw_current_vm is not None else None
                )
                if current_vm != expected_vm:
                    return False
                current_vm_status = str((current_vm or {}).get("status") or "")
                if poll:
                    if (
                        current_vm_status
                        not in {
                            "waiting_golden",
                            "waiting_capacity",
                            "waiting_headscale",
                            "waiting_preparation",
                            "provisioning",
                        }
                        or (current_vm or {}).get("provision_generation")
                        != provision_generation
                        or (current_vm or {}).get("identity_authenticated") is not False
                        or current_vm_status == "provisioning"
                        and not (current_vm or {}).get("preparation_request")
                    ):
                        return False
                elif current_vm_status in {
                    "provisioning",
                    "created",
                    "starting",
                    "ssh_pending",
                    "ready",
                    "waiting_golden",
                    "waiting_capacity",
                    "waiting_headscale",
                    "waiting_preparation",
                }:
                    return False
                if not (
                    str(row["execution_lane"] or "") == "pinned"
                    and str(row["status"] or "")
                    in {"created", "active", "awaiting_user", "suspended"}
                    and row["runtime_generation"] == parsed_runtime_generation
                    and row["runtime_retirement_token"] is None
                    and row["agent_id"] == parsed_agent
                    and row["runtime_attach_token"] == parsed_attach
                ):
                    return False
                inverse_agents = await conn.fetch(
                    "SELECT id FROM agents WHERE thread_id=$1::uuid FOR SHARE",
                    parsed_thread,
                )
                if parsed_agent is None:
                    if inverse_agents:
                        return False
                elif (
                    len(inverse_agents) != 1 or inverse_agents[0]["id"] != parsed_agent
                ):
                    return False

                # Cache construction has no physical VM identity. Keep it out
                # of metadata.vm so End can retire this runtime without
                # inventing VM/PVC UIDs or relaxing physical fencing.
                stage = metadata.get("workspace_preparation")
                if stage is not None and not isinstance(stage, dict):
                    return False
                if preparation_only:
                    if stage and stage.get("preparation_request") == preparation:
                        return dict(stage) if stage.get("status") != "failed" else False
                    if stage and stage.get("preparation_cancelled_revision") != (
                        stage.get("preparation_request") or {}
                    ).get("revision"):
                        return False
                    proposed.update(status="waiting_preparation", preparation_only=True)
                    metadata["workspace_preparation"] = proposed
                    await conn.execute(
                        "UPDATE threads SET metadata=$2::jsonb WHERE id=$1::uuid",
                        parsed_thread,
                        json.dumps(metadata),
                    )
                    return proposed
                if expected_preparation_context is not None:
                    if stage != dict(expected_preparation_context):
                        return False
                    metadata.pop("workspace_preparation", None)

                # Installing a VM generation is also the exact workspace-tier
                # transition boundary.  Session upgrades historically left
                # config_override assigned to sandbox/virtual, making the
                # subsequently authenticated VM contradict the shared
                # contract and tempting callers to let runtime readiness pick
                # a tier.  Stamp the server-owned VM assignment in the same
                # owner-locked UPDATE that precedes controller I/O.
                try:
                    contract = resolve_workspace_contract(
                        {
                            "context": metadata,
                            "config_override": metadata.get("config_override"),
                        }
                    )
                except Exception:
                    return False
                if contract.assigned_backend not in {
                    "none",
                    "virtual",
                    "sandbox",
                    "vm",
                }:
                    return False
                if contract.assigned_backend != "vm":
                    metadata[WORKSPACE_CONTRACT_CONTEXT_KEY] = {
                        "version": 1,
                        "requested_backend": "vm",
                        "assigned_backend": "vm",
                        "assignment_source": "runtime_vm_upgrade",
                    }
                    config_override = _strict_json_object(
                        metadata.get("config_override") or {},
                        label="thread VM config override",
                    )
                    workspace = _strict_json_object(
                        config_override.get("workspace") or {},
                        label="thread VM workspace config",
                    )
                    workspace["backend"] = "vm"
                    workspace.pop("remote", None)
                    config_override["workspace"] = workspace
                    metadata["config_override"] = config_override

                next_vm = {**(current_vm or {}), **proposed}
                metadata["vm"] = next_vm
                result = await conn.execute(
                    "UPDATE threads SET metadata=$2::jsonb,"
                    "last_activity=CURRENT_TIMESTAMP "
                    "WHERE id=$1::uuid AND runtime_generation=$3::uuid "
                    "AND runtime_retirement_token IS NULL",
                    parsed_thread,
                    json.dumps(metadata),
                    parsed_runtime_generation,
                )
                return result == "UPDATE 1"

    async def merge_thread_preparation_if_current(
        self, thread_id, runtime_generation, expected, updates
    ) -> bool:
        """CAS cache progress without installing physical VM authority."""
        async with self.acquire() as conn:
            return (
                await conn.execute(
                    "UPDATE threads SET metadata=jsonb_set(metadata,'{workspace_preparation}',"
                    "(metadata->'workspace_preparation') || $4::jsonb) "
                    "WHERE id=$1::uuid AND runtime_generation=$2::uuid "
                    "AND runtime_retirement_token IS NULL AND status<>'ended' "
                    "AND metadata->'workspace_preparation'=$3::jsonb",
                    UUID(str(thread_id)),
                    UUID(str(runtime_generation)),
                    json.dumps(expected),
                    json.dumps(updates),
                )
                == "UPDATE 1"
            )

    async def merge_thread_vm_context(
        self, thread_id: str, vm_updates: Dict[str, Any]
    ) -> bool:
        """Atomically merge updates into threads.metadata.vm.

        Same pattern as merge_vm_context() but targets the threads table
        metadata JSONB instead of jobs.context.

        Args:
            thread_id: Thread UUID as string
            vm_updates: Dictionary to merge into metadata.vm

        Returns:
            True if updated, False if not found
        """
        import json as json_module

        try:
            uuid_val = UUID(thread_id)
        except ValueError:
            return False

        query = (
            "UPDATE threads "
            "SET metadata = jsonb_set("
            "    COALESCE(metadata, '{}'::jsonb), "
            "    '{vm}', "
            "    COALESCE(metadata->'vm', '{}'::jsonb) || $1::jsonb"
            "), "
            "    last_activity = CURRENT_TIMESTAMP "
            "WHERE id = $2"
        )
        async with self.acquire() as conn:
            result = await conn.execute(query, json_module.dumps(vm_updates), uuid_val)

        return result == "UPDATE 1"

