    async def _persist_project_resource(self, project_id, **kwargs):
        from orchestrator.services.manifest_projects import persist_project_resource

        return await persist_project_resource(self, project_id, **kwargs)

    async def create_project(
        self,
        name: str,
        description: str | None = None,
        goal: str | None = None,
        is_default: bool = False,
        default_config_name: str | None = None,
        default_config_override: Dict[str, Any] | None = None,
        *,
        manifest_project_id: UUID | None = None,
    ) -> Dict[str, Any]:
        """Create a new project.

        Args:
            name: Project name
            description: What this project is about
            goal: Success criteria
            is_default: Whether this is a user's default project
            default_config_name: Default agent config for new jobs
            default_config_override: Default config overrides for new jobs

        Returns:
            Created project dict
        """
        async with self.acquire() as conn:
            async with conn.transaction():
                row = await conn.fetchrow(
                    """
                    INSERT INTO projects (name, description, goal, is_default,
                                          default_config_name,
                                          default_config_override, id)
                    VALUES ($1, $2, $3, $4, $5, $6, COALESCE($7::uuid, gen_random_uuid()))
                    RETURNING id, name, description, goal, status, is_default,
                              default_config_name, default_config_override,
                              nextcloud_folder_id, cloud_storage_read_only,
                              main_cloud_backend,
                              main_cloud_backend_instance_id,
                              main_cloud_folder_handle,
                              created_at, updated_at
                    """,
                    name,
                    description,
                    goal,
                    is_default,
                    default_config_name,
                    json.dumps(default_config_override)
                    if default_config_override
                    else None,
                    manifest_project_id,
                )
                # Every century has a post, whether or not an officer holds
                # it (officer_post.md §2): the vacant project_officers row is
                # born with the project. Bypassing mint paths self-heal via
                # get_or_create_project_officer.
                await conn.execute(
                    "INSERT INTO project_officers (project_id) VALUES ($1) "
                    "ON CONFLICT (project_id) DO NOTHING",
                    row["id"],
                )

        return dict(row)

    async def get_project(self, project_id: str) -> Dict[str, Any] | None:
        """Get a single project by ID.

        Args:
            project_id: Project UUID as string

        Returns:
            Project dict or None if not found
        """
        try:
            uuid_val = UUID(project_id)
        except ValueError:
            return None

        async with self.acquire() as conn:
            row = await conn.fetchrow(
                """
                SELECT id, name, description, goal, status, is_default, manifest_resource_id,
                       default_config_name, default_config_override,
                       nextcloud_folder_id, cloud_storage_read_only,
                       main_cloud_backend, main_cloud_backend_instance_id,
                       main_cloud_folder_handle,
                       network_tier,
                       (SELECT COUNT(*) FROM jobs j WHERE j.project_id = projects.id) AS job_count,
                       created_at, updated_at
                FROM projects
                WHERE id = $1
                """,
                uuid_val,
            )

        from orchestrator.services.manifest_projects import hydrate_project_row

        return await hydrate_project_row(self, row)

    async def get_workspace_network_tier(
        self, work_id: str, kind: str
    ) -> Optional[str]:
        """Resolve the network_tier of the project that owns a job/thread.

        Returns the bare tier string (e.g. ``'internet-only'``,
        ``'home-allowed'``) or ``None`` if no project mapping exists.
        The caller is responsible for applying its own default when the
        result is ``None`` — keeping the DB layer free of policy.

        Args:
            work_id: Job or thread UUID as string.
            kind: ``'job'`` or ``'thread'``.
        """
        try:
            uuid_val = UUID(work_id)
        except ValueError:
            return None

        if kind == "job":
            query = (
                "SELECT p.network_tier "
                "FROM projects p JOIN jobs j ON j.project_id = p.id "
                "WHERE j.id = $1"
            )
        elif kind == "thread":
            query = (
                "SELECT p.network_tier "
                "FROM projects p JOIN threads t ON t.project_id = p.id "
                "WHERE t.id = $1"
            )
        else:
            return None

        async with self.acquire() as conn:
            row = await conn.fetchrow(query, uuid_val)

        return row["network_tier"] if row else None

    async def get_projects_for_user(
        self, user_id: str, limit: int = 100, statuses: List[str] | None = None
    ) -> List[Dict[str, Any]]:
        """Get all projects a user is a member of.

        Args:
            user_id: User UUID as string
            limit: Maximum projects to return
            statuses: Lifecycle statuses to include. ``None`` (the default)
                applies NO filter — every existing caller, including
                ``user_visible_project_ids``, resolves *visibility* and must
                keep seeing archived projects. ``GET /api/projects`` is the
                one caller that narrows, and it passes ``['active']`` unless
                the client asked otherwise. Unknown/NULL statuses always
                survive the filter (see ``project_status_filter_sql``).

        Returns:
            List of project dicts with aggregate counts, ordered by
            is_default DESC, updated_at DESC
        """
        try:
            uuid_val = UUID(user_id)
        except ValueError:
            return []

        status_clause = ""
        params: List[Any] = [uuid_val, limit]
        if statuses is not None:
            # Lazy import for the same reason as redact_config_override above,
            # plus one this module must keep true: security.access imports
            # FastAPI, and `python -m database.migrate` loads this file through
            # database/__init__.py with only asyncpg + cryptography installed
            # (db-migrations.yml). A module-scope import here would make the
            # migration runner depend on the whole web framework.
            from orchestrator.security.access import project_status_filter_sql

            params.append(list(statuses))
            status_clause = f" AND {project_status_filter_sql('$3', column='p.status')}"

        async with self.acquire() as conn:
            rows = await conn.fetch(
                f"""
                SELECT p.id, p.name, p.description, p.goal, p.status,
                       p.is_default, p.default_config_name, p.manifest_resource_id,
                       p.nextcloud_folder_id, p.cloud_storage_read_only,
                       p.main_cloud_backend, p.main_cloud_backend_instance_id,
                       p.main_cloud_folder_handle,
                       p.created_at, p.updated_at,
                       pm.role AS user_role,
                       (SELECT COUNT(*) FROM jobs j WHERE j.project_id = p.id) AS job_count,
                       (SELECT COUNT(*) FROM project_repositories pr WHERE pr.project_id = p.id) AS repo_count,
                       (SELECT COUNT(*) FROM project_members pm2 WHERE pm2.project_id = p.id) AS member_count
                FROM projects p
                JOIN project_members pm ON p.id = pm.project_id
                WHERE pm.user_id = $1{status_clause}
                ORDER BY p.is_default DESC, p.updated_at DESC
                LIMIT $2
                """,
                *params,
            )

        from orchestrator.services.manifest_projects import hydrate_project_row

        return [await hydrate_project_row(self, row) for row in rows]

    async def park_project_jobs_for_archive(self, project_id: str) -> int:
        """Park every not-yet-started job in ``project_id``. Returns the count.

        Archiving a project quiesces its children rather than refusing
        (§4.5 of
        knowledge-base/knowledge/features/project_and_job_list_filtering.md).
        A job the dispatcher has not claimed yet is *new work*: it is parked
        by setting ``freeze_data``, which ``claim_job_for_agent`` and
        ``get_dispatchable_jobs`` both require to be NULL. ``processing``
        jobs are deliberately untouched — they are in-flight work, and
        killing them is not what "archive" means.

        ``project_archived`` is intentionally absent from every set in
        ``src/shared/job_freeze_types.py``, so no sweeper auto-redispatches
        these: unarchiving reactivates the container and leaves the parked
        children parked, awaiting an explicit resume.
        """
        try:
            uuid_val = UUID(project_id)
        except (ValueError, TypeError):
            return 0

        freeze = json.dumps(
            {
                "freeze_type": "project_archived",
                "origin": "project_archive",
                "frozen_at": datetime.now(timezone.utc).isoformat(),
                "error_summary": (
                    "Parked: this job's project was archived before the job "
                    "started. Unarchive the project and resume the job to run it."
                ),
            }
        )
        async with self.acquire() as conn:
            rows = await conn.fetch(
                """
                UPDATE jobs
                   SET status = 'paused',
                       freeze_data = $2::jsonb,
                       updated_at = CURRENT_TIMESTAMP
                 WHERE project_id = $1
                   AND status IN ('created', 'paused')
                   AND assigned_agent_id IS NULL
                   AND freeze_data IS NULL
                RETURNING id
                """,
                uuid_val,
                freeze,
            )
        return len(rows)

    async def update_project(self, project_id: str, **kwargs) -> bool:
        """Update a project.

        Args:
            project_id: Project UUID
            **kwargs: Fields to update (name, description, goal, status,
                      default_config_name, default_config_override,
                      nextcloud_folder_id, cloud_storage_read_only)

        Returns:
            True if updated, False if not found
        """
        try:
            uuid_val = UUID(project_id)
        except ValueError:
            return False

        allowed_fields = {
            "name",
            "description",
            "goal",
            "status",
            "default_config_name",
            "default_config_override",
            "nextcloud_folder_id",
            "cloud_storage_read_only",
            "main_cloud_backend",
            "main_cloud_backend_instance_id",
            "main_cloud_folder_handle",
            # Admin-only at the API layer (orchestrator/main.py update_project);
            # listed here so the DB UPDATE path accepts it once authorized.
            "network_tier",
        }

        updates = []
        values = []
        param_count = 0

        for key, value in kwargs.items():
            if key not in allowed_fields or value is None:
                continue
            param_count += 1
            updates.append(f"{key} = ${param_count}")
            if key == "default_config_override":
                values.append(json.dumps(value) if isinstance(value, dict) else value)
            elif key == "main_cloud_backend_instance_id":
                values.append(UUID(str(value)))
            else:
                values.append(value)

        if not updates:
            return False

        param_count += 1
        values.append(uuid_val)

        query = f"UPDATE projects SET {', '.join(updates)} WHERE id = ${param_count}"

        async with self.transaction_scope():
            await self._lock_expert_catalog()
            result = await self.execute(query, *values)
            if result == "UPDATE 1" and set(kwargs) & {
                "name",
                "description",
                "default_config_name",
                "default_config_override",
            }:
                await self._persist_project_resource(
                    project_id,
                    project_changes={
                        key: value for key, value in kwargs.items() if value is not None
                    },
                )
        return result == "UPDATE 1"

    async def delete_project(self, project_id: str) -> bool:
        """Delete a project (cascades to members, repos).

        Args:
            project_id: Project UUID

        Returns:
            True if deleted, False if not found
        """
        try:
            uuid_val = UUID(project_id)
        except ValueError:
            return False

        async with self.acquire() as conn:
            async with conn.transaction():
                from orchestrator.services.manifest_retirement import (
                    retire_project_resources,
                )

                await retire_project_resources(conn, uuid_val)
                # No FK cascade fires on capability_grants.scope_id (polymorphic);
                # delete the project's grant rows in-band so removal stays atomic.
                await self.delete_grants_for_scope(
                    conn, scope_kind="project", scope_id=project_id
                )
                # Match the connector-edit lock order (datasource parent,
                # junction child) before the project FK cascade reaches the
                # same rows. Stable ordering also prevents two project deletes
                # sharing connectors from acquiring parent locks inversely.
                await conn.fetch(
                    """
                    SELECT d.id
                    FROM datasources d
                    JOIN project_datasources pd ON pd.datasource_id = d.id
                    WHERE pd.project_id = $1
                    ORDER BY d.id
                    FOR UPDATE OF d
                    """,
                    uuid_val,
                )
                # Native KB connectors are project-owned synthetic rows. Their
                # project link would otherwise cascade away while the
                # datasource itself survived as an unreachable orphan. Match
                # the server-owned marker exactly and remove the datasource
                # before deleting its project in the same transaction.
                await conn.execute(
                    """
                    DELETE FROM datasources
                    WHERE type = 'kb'
                      AND CASE
                          WHEN config->>'native_project_id' ~*
                               '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                          THEN (config->>'native_project_id')::uuid
                          ELSE NULL
                      END = $1
                    """,
                    uuid_val,
                )
                result = await conn.execute(
                    "DELETE FROM projects WHERE id = $1",
                    uuid_val,
                )

        return result == "DELETE 1"

    # -- Project Members --

    async def add_project_member(
        self,
        project_id: str,
        user_id: str,
        role: str = "editor",
        *,
        defer_manifest: bool = False,
    ) -> Dict[str, Any]:
        """Add a member to a project.

        Args:
            project_id: Project UUID
            user_id: User UUID
            role: Member role (owner, editor, viewer)

        Returns:
            Member dict with user info
        """
        project_uuid = UUID(project_id)
        user_uuid = UUID(user_id)

        async with self.transaction_scope():
            await self._lock_expert_catalog()
            async with self.acquire() as conn:
                row = await conn.fetchrow(
                    """
                    INSERT INTO project_members (project_id, user_id, role)
                    VALUES ($1, $2, $3)
                    RETURNING project_id, user_id, role, added_at AS joined_at
                    """,
                    project_uuid,
                    user_uuid,
                    role,
                )

                # Fetch user info for display
                user_row = await conn.fetchrow(
                    "SELECT display_name, avatar_color FROM users WHERE id = $1",
                    user_uuid,
                )

            if role == "owner" and not defer_manifest:
                from orchestrator.services.manifest_store import ManifestStore

                if await ManifestStore(self).by_link("Project", project_uuid) is None:
                    await self._persist_project_resource(project_id, owner_id=user_id)

        result = dict(row)
        if user_row:
            result["display_name"] = user_row["display_name"]
            result["avatar_color"] = user_row["avatar_color"]

        return result

    async def get_project_members(self, project_id: str) -> List[Dict[str, Any]]:
        """Get all members of a project with user info.

        Args:
            project_id: Project UUID

        Returns:
            List of member dicts with user display info
        """
        try:
            uuid_val = UUID(project_id)
        except ValueError:
            return []

        async with self.acquire() as conn:
            rows = await conn.fetch(
                """
                SELECT pm.project_id, pm.user_id, pm.role,
                       pm.added_at AS joined_at,
                       u.display_name, u.avatar_color, u.email
                FROM project_members pm
                JOIN users u ON pm.user_id = u.id
                WHERE pm.project_id = $1
                ORDER BY pm.added_at ASC
                """,
                uuid_val,
            )

        return [dict(row) for row in rows]

